(()=>{'use strict';
const $=id=>document.getElementById(id),API='https://rotacerta-mobile.carlosjralfa.chatgpt.site/api/spx',params=new URLSearchParams(location.hash.slice(1)),route=params.get('route'),token=params.get('token');
let current=null,map=null,destination=null,driver=null,loaded=false,busy=false,stopped=false;
const say=(message,error=false)=>{$('status').textContent=message;$('status').classList.toggle('error',error);};
function other(){const yes=$('receiver').value==='Outra pessoa';$('other').hidden=!yes;$('name').required=yes;}
function paintMap(){if(!map||!current)return;if(!destination){destination=L.marker([current.destination.lat,current.destination.lon]).addTo(map).bindTooltip('Seu endereço');map.setView(destination.getLatLng(),16);}if(current.position){const p=current.position;if(driver)driver.setLatLng([p.lat,p.lon]);else driver=L.circleMarker([p.lat,p.lon],{radius:9,color:'#fff',weight:2,fillColor:'#ee4d2d',fillOpacity:1}).addTo(map).bindTooltip('Entregador');map.fitBounds(L.featureGroup([destination,driver]).getBounds().pad(.2),{maxZoom:16});}else if(driver){driver.remove();driver=null;map.setView(destination.getLatLng(),16);}}
function render(data){current=data;$('delivery').hidden=false;$('replyBox').hidden=false;$('order').textContent=data.orderRef;$('address').textContent=[data.street,data.municipality].filter(Boolean).join(' · ');$('stage').textContent=({waiting:'NA ROTA',next:'A CAMINHO DE VOCÊ',paused:'PARADA EM ANDAMENTO',delivered:'ENTREGA CONCLUÍDA',ended:'ACOMPANHAMENTO ENCERRADO'})[data.status]||'NA ROTA';$('eta').textContent=data.eta?'Previsão aproximada: '+new Date(data.eta).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})+' · sem trânsito ao vivo.':data.status==='waiting'?'O entregador ainda vai iniciar o percurso até você.':'Sem previsão disponível neste momento.';$('gpsInfo').textContent=data.position?'Última posição: '+new Date(data.position.observedAt).toLocaleTimeString('pt-BR')+' · precisão aproximada de '+Math.round(data.position.accuracy||0)+' m.':data.status==='next'?'Aguardando uma posição atualizada do entregador.':'A localização do entregador não está sendo exibida.';
const ended=['delivered','ended'].includes(data.status);$('fields').disabled=ended;if(ended)$('replyStatus').textContent='Este pedido não recebe mais respostas.';
if(!loaded){if(data.response){for(const key of ['home','receiver','name','phone','keyword','notes'])$(key).value=data.response[key]||'';$('replyStatus').textContent='Sua resposta já foi enviada. Você pode atualizar abaixo.';}other();loaded=true;}paintMap();}
async function request(response){const r=await fetch(API+(response?'':'?route='+encodeURIComponent(route)),{method:response?'POST':'GET',headers:{Authorization:'Bearer '+token,...(response?{'Content-Type':'application/json'}:{})},...(response?{body:JSON.stringify({action:'reply',routeId:route,response})}:{}),signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok){const e=new Error(data.error||'Falha de comunicação');e.status=r.status;throw e;}return data;}
async function refresh(){if(stopped||busy)return;busy=true;try{render(await request());say('Acompanhamento atualizado.');}catch(e){say(e.message||'Sem conexão. Tentando novamente…',true);if(current){current.position=null;paintMap();$('gpsInfo').textContent='Sem atualização de localização.';}if([401,403,404,410].includes(e.status)){stopped=true;$('fields').disabled=true;$('replyBox').hidden=true;}}finally{busy=false;}}
$('receiver').onchange=other;$('showMap').onclick=()=>{if(!window.L)return say('Mapa não carregou. Confira a conexão e recarregue.',true);if(!map){$('map').hidden=false;map=L.map('map');L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);paintMap();}$('showMap').hidden=true;};
$('replyForm').onsubmit=async e=>{e.preventDefault();const response=Object.fromEntries(['home','receiver','name','phone','keyword','notes'].map(k=>[k,$(k).value]));$('submit').disabled=true;$('replyStatus').textContent='Enviando…';try{for(let i=0;i<3;i++){try{await request(response);break;}catch(err){if(err.status!==409||i===2)throw err;}}$('replyStatus').textContent='Resposta enviada ao entregador!';$('replyStatus').className='success';}catch(err){$('replyStatus').className='status error';$('replyStatus').textContent=err.message;}finally{$('submit').disabled=false;}};
if(!/^[a-f0-9-]{36}$/.test(route||'')||!/^[a-f0-9]{64}$/.test(token||'')){say('Link incompleto. Abra o link enviado pelo seu entregador.',true);return;}refresh();setInterval(refresh,15000);setInterval(()=>{if(current?.position&&Date.now()-current.position.observedAt>=60000){current.position=null;paintMap();$('gpsInfo').textContent='Aguardando atualização da localização.';}},5000);
})();
